<?php require __DIR__.'/includes/bootstrap.php';$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM construction_documents WHERE id=?');$s->execute([$id]);$d=$s->fetch();if(!$d||!dev_can_access((int)$d['construction_project_id'])){http_response_code(404);exit('Not found.');}$path=__DIR__.'/../'.$d['file_path'];if(!is_file($path)){http_response_code(404);exit('File missing.');}header('Content-Type: '.($d['mime_type']?:'application/octet-stream'));header('Content-Disposition: attachment; filename="'.str_replace('"','',$d['original_name']).'"');header('Content-Length: '.filesize($path));readfile($path);
